insert into nad_support_meeting (
    ticket_id, student_id, staff_id, start_time, duration_minutes, status, meeting_url, create_by, create_time
) values (
    #{ticketId}, #{studentId}, #{staffId}, #{startTime}, #{durationMinutes}, #{status}, #{meetingUrl}, #{createBy}, now()
)

mapper.select:
select count(*) from nad_support_meeting
where staff_id = #{staffId} and status = 'SCHEDULED'
  and start_time < #{end}
  and date_add(start_time, interval duration_minutes minute) > #{start}

select count(*) from nad_support_meeting
where student_id = #{studentId} and status = 'SCHEDULED'
  and start_time < #{end}
  and date_add(start_time, interval duration_minutes minute) > #{start}
